/**
 * Dependency-free static server for the prebuilt dev shell UI (`dist/`).
 *
 * The published UI is a plain Vite build, so the block registry can't ride in
 * through build-time `import.meta.env` vars the way it does under
 * `scripts/dev.ts`. Instead, this server injects a `window.__DEV_SHELL_CONFIG__`
 * script into `index.html` as it is served; `src/helpers/blocks.ts` prefers
 * that global over the baked-in env values.
 */
import { readFileSync } from "node:fs";
import { extname, join, normalize, resolve, sep } from "node:path";
import { formatUnknownError } from "./errors.js";
const CONTENT_TYPES = {
    ".html": "text/html; charset=utf-8",
    ".js": "text/javascript; charset=utf-8",
    ".mjs": "text/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".ico": "image/x-icon",
    ".woff": "font/woff",
    ".woff2": "font/woff2",
    ".map": "application/json; charset=utf-8",
};
/** `index.html` with the runtime config injected ahead of the bundle script. */
function injectConfig(html, config) {
    const tag = `<script>window.__DEV_SHELL_CONFIG__ = ${JSON.stringify(config).replace(/</g, "\\u003c")}</script>`;
    if (html.includes("<head>")) {
        return html.replace("<head>", `<head>\n\t\t${tag}`);
    }
    return `${tag}\n${html}`;
}
/**
 * Serve `distDir` as a request handler. Unknown extensionless paths fall back to
 * `index.html`.
 *
 * `addPrebuiltData`, when given, backs `POST /api/prebuilt-data`: it writes
 * the pre-built sources into the worker's data directory and returns
 * the directory's updated contents.
 */
export function createUiHandler(distDir, config, addPrebuiltData) {
    const dist = resolve(distDir);
    const rawIndexHtml = readFileSync(join(dist, "index.html"), "utf-8");
    // Server-owned: updated by the add endpoint, while the caller's `config`
    // stays an untouched input.
    let dataSources = config.dataSources;
    return (req, res) => {
        let urlPath;
        try {
            urlPath = decodeURIComponent(req.url?.split("?", 1)[0] ?? "/");
        }
        catch {
            res.writeHead(400);
            res.end();
            return;
        }
        // Routed on the raw URL path: normalize() is platform-specific, so it
        // would rewrite "/api/..." to "\api\..." on Windows and never match.
        if (urlPath === "/api/prebuilt-data") {
            if (req.method !== "POST") {
                res.writeHead(405, { Allow: "POST" });
                res.end();
                return;
            }
            if (addPrebuiltData === undefined) {
                res.writeHead(404);
                res.end();
                return;
            }
            try {
                dataSources = addPrebuiltData();
            }
            catch (error) {
                res.writeHead(500, { "Content-Type": CONTENT_TYPES[".json"] });
                res.end(JSON.stringify({ error: formatUnknownError(error) }));
                return;
            }
            res.writeHead(200, { "Content-Type": CONTENT_TYPES[".json"] });
            res.end(JSON.stringify({ dataSources }));
            return;
        }
        const path = normalize(urlPath);
        const filePath = join(dist, path);
        if (!filePath.startsWith(dist + sep) && filePath !== dist) {
            res.writeHead(403);
            res.end();
            return;
        }
        const ext = extname(filePath);
        if (path === "/" || path === `${sep}index.html` || ext === "") {
            res.writeHead(200, { "Content-Type": CONTENT_TYPES[".html"] });
            // Injected per request: `dataSources` changes when pre-built data is
            // added, and a reload must see the updated collection.
            res.end(injectConfig(rawIndexHtml, { ...config, dataSources }));
            return;
        }
        try {
            const body = readFileSync(filePath);
            res.writeHead(200, {
                "Content-Type": CONTENT_TYPES[ext] ?? "application/octet-stream",
            });
            res.end(body);
        }
        catch {
            res.writeHead(404);
            res.end();
        }
    };
}
